const NAV=[['home','工作台','home'],['fpga','FPGA 下载','chip'],['mcu','MCU 调试','code'],['uart','串口终端','terminal'],['flash','SPI Flash','flash'],['i2c','I²C / SPI','nodes'],['gpio','GPIO 控制','gpio'],['jtag','JTAG / XVC','scan'],['logic','逻辑分析仪','gpio'],['scope','数字示波器','scan'],['firmwares','RP2040 固件','download'],['history','任务记录','history'],['wiring','接线与模式','book'],['setup','连接设置','settings']];
const META={logic:['LOGIC ANALYZER','逻辑分析仪','8 通道同步采集，检查时序、触发事件并导出波形。'],scope:['DIGITAL OSCILLOSCOPE','数字示波器','使用 RP2040 ADC 采集模拟信号，测量电压与时间。'],firmwares:['BOARD FIRMWARE','RP2040 固件与接线','为你的 LA_RP2040 板卡切换调试、逻辑分析和 ADC 采集功能。'],home:['WORKSPACE','调试，从这里开始','连接 CH347 或 RP2040，让下载、调试与信号测量在一个工作台完成。'],fpga:['PROGRAM & VERIFY','FPGA 下载','通过 openFPGALoader 扫描 JTAG 链、加载 SRAM 或写入配置 Flash。'],mcu:['DEBUG SESSION','MCU 调试','通过 OpenOCD 连接目标，烧录固件并执行调试操作。'],uart:['SERIAL CONSOLE','串口终端','查看启动日志、发送命令。模式 0 支持两个独立串口。'],flash:['SPI FLASH PROGRAMMER','SPI Flash','使用 flashrom 识别、备份、写入和校验外部 SPI Flash。'],i2c:['BUS EXPLORER','I²C / SPI 总线','探索设备地址、读写寄存器，或发送 SPI 全双工事务。'],gpio:['DIGITAL I/O','GPIO 控制','通过 WCH SDK 访问开放的数字引脚，检查输入与驱动输出。'],jtag:['SCAN & BRIDGE','JTAG / XVC','执行 SVF 向量，或为本机 FPGA 工具提供 Xilinx Virtual Cable。'],history:['ACTIVITY','任务记录','保留每次执行的文件校验值、设备模式、日志与最终状态。'],wiring:['HARDWARE REFERENCE','接线与模式','以实际引脚复用和目标电压为准，切换模式后重新上电。'],setup:['LOCAL AGENT','连接设置','网页负责任务编排，本地 Agent 负责 USB 访问和工具执行。']};
const OP={'logic.capture':['采集逻辑波形',[5],false],'scope.capture':['采集 ADC 波形',[7],false], 'fpga.detect':['扫描 JTAG 链',[3],false],'fpga.sram':['加载 SRAM',[3],true],'fpga.flash':['写入配置 Flash',[3],true],'flash.detect':['识别 Flash',[1],false],'flash.read':['备份 Flash',[1],false],'flash.write':['写入 Flash',[1],true],'flash.verify':['校验 Flash',[1],false],'flash.erase':['擦除 Flash',[1],true],'mcu.start':['启动调试',[3,4],true],'mcu.stop':['停止调试',[3,4],false],'mcu.halt':['暂停',[3,4],true],'mcu.resume':['继续',[3,4],true],'mcu.step':['单步',[3,4],true],'mcu.reset':['复位并暂停',[3,4],true],'mcu.registers':['读取寄存器',[3,4],false],'mcu.memory':['读取内存',[3,4],false],'mcu.program':['烧录固件',[3,4],true],'uart.open':['打开串口',[0,1,2,3,4],false],'uart.close':['关闭串口',[0,1,2,3,4],false],'uart.send':['发送数据',[0,1,2,3,4],true],'i2c.scan':['扫描地址',[1,2],false],'i2c.read':['读取寄存器',[1,2],false],'i2c.write':['写入寄存器',[1,2],true],'spi.transfer':['传输数据',[1,2],true],'gpio.read':['读取电平',[3],false],'gpio.write':['设置输出',[3],true],'jtag.svf':['执行 SVF',[3],true],'xvc.start':['启动 XVC',[3],true],'xvc.stop':['停止 XVC',[3],false]};
const FILE_OPS=['fpga.sram','fpga.flash','flash.write','flash.verify','mcu.program','jtag.svf'];
let state={page:'home',demo:true,connected:false,mode:3,token:'',base:'http://127.0.0.1:8765',status:null,device:null,jobs:[],demoJobs:[],activeJob:null,files:{},forms:{},answer:'',busy:false,uart:[],plan:null}, pollTimer, toastTimer;
const formDefaults={logic:{rate:1000000,samples:4096,trigger:'none',trigger_channel:0,timeout:15},scope:{rate:100000,samples:4096,channel:0,vref:3.3,timeout:15},fpga:{freq:'1000000'},mcu:{target:'stm32f1',transport:'swd',freq:'1000000',address:'0x20000000',count:16},uart:{port:'',baud:115200,channel:1,text:'help\r\n'},flash:{chip:''},i2c:{address:'0x68',register:'0x75',reg_width:1,length:16,data:'00',freq:'1000000',spi_mode:0,spi_data:'9F 00 00 00'},gpio:{pin:3,value:0},jtag:{freq:'1000000',irlen:8,idcode:'0x012ba043'}};
const getform=p=>state.forms[p]??(state.forms[p]={...formDefaults[p]});
const currentJobs=()=>state.demo?state.demoJobs:state.jobs;
const badge=()=>`<span class="status ${state.demo?'demo':state.connected?'real':''}"><span class="dot" style="background:${state.demo?'#bea575':state.connected?'#4cae8c':'#aab8b8'}"></span>${state.demo?'演示模式 · 未连接硬件':state.connected?'本地 Agent 已连接':'本地 Agent 未连接'}</span>`;
function toast(m){$('#toast').textContent=m;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function nav(p){state.page=p;if(state.demo&&['logic','scope'].includes(p))state.mode=p==='logic'?5:7;state.answer='';render();window.scrollTo({top:0,behavior:'smooth'})}
function field(label,key,value,opts){const choices=opts?.choices;return `<div class="field ${opts?.full?'full':''}"><label for="f-${key}">${label}</label>${choices?`<select id="f-${key}" data-field="${key}">${choices.map(x=>`<option value="${esc(x[0])}" ${String(x[0])===String(value)?'selected':''}>${esc(x[1])}</option>`).join('')}</select>`:opts?.area?`<textarea id="f-${key}" data-field="${key}" spellcheck="false">${esc(value)}</textarea>`:`<input id="f-${key}" data-field="${key}" value="${esc(value)}" ${opts?.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} autocomplete="off">`}${opts?.help?`<small>${opts.help}</small>`:''}</div>`}
const freq=v=>field('时钟频率','freq',v,{choices:[['500000','500 kHz'],['1000000','1 MHz'],['5000000','5 MHz'],['10000000','10 MHz'],['15000000','15 MHz'],['30000000','30 MHz']]});
const button=(op,primary=false)=>`<button data-op="${op}" class="${primary?'primary':''}" ${state.busy?'disabled':''}>${icon(op.includes('stop')?'stop':op.includes('detect')||op.includes('scan')?'scan':op.includes('read')||op.includes('registers')?'file':'play')}${OP[op][0]}</button>`;
function upload(accept){const f=state.files[state.page];return `<label class="dropzone" id="dropzone">${icon(f?'file':'download')}<b>${f?esc(f.name):'拖入文件，或点击选择'}</b><span>${f?(f.size/1024).toFixed(1)+' KB · 已计算 SHA-256':esc(accept)+' · 最大 64 MiB'}</span><input type="file" id="firmware" accept="${accept}" aria-label="选择固件文件">${f?`<div class="file-hash">SHA256 ${esc(f.sha256)}</div>`:''}</label>`}
function board(){return `<svg class="board" viewBox="0 0 370 220" role="img" aria-label="CH347 四模式连接示意"><defs><pattern id="dots" width="14" height="14" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".6" fill="#d9e6df"/></pattern></defs><rect width="370" height="220" fill="url(#dots)"/><g fill="none" stroke="#c6dbcf" stroke-width="1.2"><path d="M0 110h75l23-24h40M35 160h63l25-28h15M232 84h35l20-26h66M232 136h30l24 25h83M185 46V19m0 156v30"/><path d="M18 86h45l23-25h38M243 105h68M208 46V8m-45 167v35"/></g><rect x="104" y="48" width="161" height="126" rx="15" fill="#e6f1e9" stroke="#c5dccd"/><rect x="113" y="57" width="143" height="108" rx="11" fill="#f7fbf7" stroke="#d2e3d6"/><g fill="#b0cabc">${[0,1,2,3,4,5,6].map(i=>`<rect x="135" y="${72+i*12}" width="10" height="5" rx="1"/><rect x="225" y="${72+i*12}" width="10" height="5" rx="1"/>`).join('')}</g><rect x="144" y="65" width="82" height="88" rx="4" fill="#25463c" stroke="#729b7f"/><rect x="150" y="71" width="70" height="76" rx="2" fill="none" stroke="#44685a"/><circle cx="155" cy="78" r="2" fill="#7baa8d"/><text x="185" y="105" text-anchor="middle" fill="#e0f0e0" font-family="monospace" font-size="16">CH347</text><text x="185" y="122" text-anchor="middle" fill="#81a890" font-family="monospace" font-size="7" letter-spacing="2">MULTI-PROTOCOL</text><circle cx="76" cy="110" r="4" fill="#eaf4ed" stroke="#8bb99c"/><circle cx="286" cy="161" r="4" fill="#eaf4ed" stroke="#8bb99c"/><circle cx="286" cy="58" r="4" fill="#eaf4ed" stroke="#8bb99c"/><g font-family="monospace" font-size="8" fill="#8aa592"><text x="21" y="101">USB 2.0</text><text x="292" y="49">JTAG</text><text x="310" y="97">UART</text><text x="293" y="178">SPI / I²C</text><text x="152" y="198">4 MODES · 1 AGENT</text></g></svg>`}
function modeCards(){return `<div class="section-title"><h2>选择工作模式</h2><span>${state.demo?'预览下一版硬件的四种模式':'实际模式由 USB PID 识别'}</span></div><div class="mode-grid">${MODES.map((m,i)=>`<button class="mode-card ${state.mode===i?'selected':''}" data-mode="${i}"><div class="mode-row"><span class="mode-num">MODE 0${i}</span><span class="mode-dot"></span></div><h3>${m.name}</h3><p>${m.desc}</p><div class="mode-foot"><span>${m.strap}</span><em>${state.mode===i?(state.demo?'正在预览':state.device?.mode===i?'实际模式':'准备模式'):'PID '+m.pid}</em></div></button>`).join('')}</div><div class="notice">${icon('info')}<span>软件选择用于准备任务。切换实际模式需调整 DTR1 / RTS1 硬件电平并重新上电。</span></div>`}
function shortcut(p,sub){const n=NAV.find(x=>x[0]===p);return `<button class="shortcut" data-nav="${p}"><span class="shortcut-icon">${icon(n[2])}</span><span class="shortcut-text"><b>${n[1]}</b><small>${sub}</small></span><span class="arrow">↗</span></button>`}
function dependency(){return `<section class="panel"><div class="panel-header"><h2>${icon('check')}运行环境</h2><button class="small ghost" data-nav="setup">查看详情 ${icon('arrow')}</button></div><div class="panel-body">${[['Agent 本地服务',state.connected],['openFPGALoader',state.status?.tools?.openFPGALoader],['OpenOCD',state.status?.tools?.openocd],['flashrom',state.status?.tools?.flashrom]].map(([n,v])=>`<div class="check-row"><span>${icon(v?'check':'info')}${n}</span><em class="${v?'yes':''}">${v?'已就绪':state.connected?'未安装':'等待连接'}</em></div>`).join('')}<div class="dependency-note">${state.connected?'工具可用性来自本机检查；能否调试具体目标仍取决于工具版本和目标支持。':'连接本地 Agent 后自动检查依赖、设备模式和芯片版本。浏览器不直接占用 USB。'}</div></div></section>`}
function assistant(){return `<section class="panel assistant-panel"><div class="assistant-icon">${icon('spark')}</div><div class="assistant-content"><div class="assistant-title">任务助手 <span class="tiny">${state.status?.ai&&!state.demo?'EVE AI · 已配置':'本地规则助手 · 无需模型'}</span></div><form id="ask-form" class="assistant-input"><input id="ask-input" aria-label="描述你的调试任务" placeholder="描述你的任务，例如：备份 SPI Flash，或给 FPGA 下载 bit 文件" maxlength="6000"><button class="primary" type="submit" aria-label="发送任务">${icon('arrow')}</button></form><div class="suggestions"><button data-ask="我要给 FPGA 下载 bit 文件">下载 FPGA 文件</button><button data-ask="备份 SPI Flash">备份 Flash</button><button data-ask="我想调试 STM32">调试 STM32</button></div>${state.answer?`<div class="answer">${esc(state.answer)}</div>`:''}</div></section>`}
function home(){return `<section class="panel hero"><div><div class="hero-label"><span class="dot"></span>YOUR HARDWARE, CONNECTED.</div><h2>连接设备，看见每一个信号。</h2><p>从 FPGA 下载、MCU 调试，到数字时序与模拟波形。<br>把每个操作，变成可预览、可验证、可追溯的任务。</p><div class="hero-actions"><button class="primary" data-connect>${icon('plug')}${state.connected?'管理连接':'连接调试器'}</button><button data-nav="wiring">查看接线指南 ${icon('arrow')}</button></div><div class="hero-meta"><div>目标接口<b>JTAG / SWD</b></div><div>通信接口<b>UART / SPI / I²C</b></div><div>信号测量<b>LOGIC / ADC</b></div><div>执行方式<b>LOCAL AGENT</b></div></div></div>${board()}</section>${state.mode<=3?modeCards():`<div class="notice">${modeName(state.mode)} · 功能由板上固件决定；切换配置需要重新刷写 UF2。</div>`}<div class="workspace-grid"><section class="panel"><div class="panel-header"><h2>${icon('flash')}开始一个任务</h2><span class="subtle">常用工具</span></div><div class="panel-body shortcuts">${shortcut('fpga','扫描 · 加载 · 固化')}${shortcut('mcu','连接 · 烧录 · 单步')}${shortcut('uart','串口 · 日志 · 命令')}${shortcut('flash','识别 · 备份 · 校验')}${shortcut('logic','8 通道 · 触发 · 波形')}${shortcut('scope','ADC · 电压 · 游标')}</div></section>${dependency()}</div>${assistant()}`}
function output(){const j=state.activeJob;return `<section class="panel" id="output-panel"><div class="panel-header"><h2>${icon('terminal')}执行输出</h2><span class="terminal-status">${state.demo?'DEMO':j?'LIVE':'READY'}</span></div>${j?`${['queued','running'].includes(j.status)?'<div class="scroll-status"></div>':''}<div class="terminal" id="terminal-output">${esc((j.logs||[]).join('\n'))}</div>${j.result?`<div class="result">${esc(JSON.stringify(Object.fromEntries(Object.entries(j.result).filter(([k])=>k!=='samples_b64')),null,2))}</div>`:''}<div class="output-actions"><span class="badge ${j.status}" style="margin-right:auto">${statusText(j.status)}</span>${j.result?.download?'<button class="small" data-download>下载备份</button>':''}${['running','queued'].includes(j.status)?'<button class="small danger" data-cancel>取消任务</button>':'<button class="small" data-export-job>导出日志</button>'}</div>`:'<div class="empty-output"><div>'+icon('terminal')+'<br>执行任务后，实时输出会显示在这里。<br><span class="subtle">日志与文件 SHA-256 一起保存</span></div></div>'}</section>`}
function deviceSummary(){return `<section class="panel" style="margin-top:18px"><div class="panel-header"><h2>${icon('plug')}当前连接</h2><span class="badge">${state.demo?'演示':'真实硬件'}</span></div><div class="summary-list"><div class="summary-line"><span>调试器</span><b>${state.demo?modeName(state.mode)+' · 示例设备':esc(state.device?.name||'未检测到设备')}</b></div><div class="summary-line"><span>实际模式</span><b>${state.demo?'未连接':state.device?modeName(state.device.mode)+' / '+state.device.pid:'—'}</b></div>${state.device?.family==='rp2040'&&!state.device.board_match?'<div class="warning">此 USB 设备未确认使用本板专用固件。请核对实际引脚映射；固件页提供适配 LA_RP2040 的 UF2。</div>':''}<div class="summary-line"><span>芯片版本</span><b>${state.demo?'—':esc(state.device?.version||'—')}</b></div><div class="summary-line"><span>任务准备模式</span><b>${modeName(state.mode)}</b></div><div class="summary-line"><span>目标电压</span><b>3.3 V · 请核实硬件</b></div></div></section>`}
function workspace(body,title,help){return `${state.demo?'<div class="warning">演示模式：操作使用示例结果，不会访问 USB 或写入目标。点击右上角“连接调试器”进入真实模式。</div>':!state.device?'<div class="warning">尚未选择调试器。请连接本地 Agent 并插入调试器。</div>':''}<div class="workspace-grid" style="margin-top:0"><section class="panel"><div class="panel-header"><h2>${icon(NAV.find(x=>x[0]===state.page)[2])}${title}</h2><span class="pill">${modeName(state.mode)}</span></div><div class="panel-body">${body}${help?`<div class="help-box">${help}</div>`:''}</div></section><div>${output()}${deviceSummary()}</div></div>${assistant()}`}
function toolPage(){const p=getform(state.page);let b='',help='',title='任务参数';switch(state.page){case 'fpga':b=`<div class="form-grid">${field('下载线','cable','ch347_jtag',{choices:[['ch347_jtag','CH347 JTAG / openFPGALoader']]})}${freq(p.freq)}<div class="field full"><label>FPGA 配置文件</label>${upload('.bit,.bin,.jed,.fs,.mcs')}</div></div><div class="buttons">${button('fpga.detect')}${button('fpga.sram',true)}${button('fpga.flash')}</div>`;help='需要模式 3。先扫描 JTAG 链，再选择匹配目标的文件。SRAM 配置断电丢失；Flash 写入会修改持久配置。具体器件及文件格式由 openFPGALoader 支持情况决定。';break;
case 'mcu':b=`<div class="form-grid">${field('目标系列','target',p.target,{choices:[['stm32f1','STM32 F1'],['stm32f4','STM32 F4'],['rp2040','Raspberry Pi RP2040'],['nrf52','Nordic nRF52'],['esp32','Espressif ESP32（JTAG）']]})}${field('调试接口','transport',p.transport,{choices:state.mode===4?[['swd','SWD']]:[['swd','SWD'],['jtag','JTAG']]})}${state.mode===4?field('SWD 时钟','freq',p.freq,{choices:[[100000,'100 kHz'],[500000,'500 kHz'],[1000000,'1 MHz']]}):freq(p.freq)}${field('读取字数 / 32 bit','count',p.count)}${field('内存地址','address',p.address,{full:true})}<div class="field full"><label>固件文件（烧录时需要）</label>${upload('.elf,.hex')}</div></div><div class="buttons">${button('mcu.start',true)}${button('mcu.stop')}${button('mcu.program')}</div><div class="buttons">${['halt','resume','step','reset','registers','memory'].map(x=>button('mcu.'+x)).join('')}</div>`;help=state.mode===4?'本板调试固件提供 CMSIS-DAP v2 SWD。使用 OpenOCD 的 cmsis-dap 驱动；不支持 JTAG、SWO 或 openFPGALoader。首版 SWD 上限 1 MHz，GDB 连接 127.0.0.1:3333。接线见 RP2040 固件页。':'需要支持 CH347 驱动的新版 OpenOCD。CH347T 2.41 不支持原生 SWD；4.41/5.44 仍需真机验证，此版本统一限制 SWD 到 1 MHz。GDB 端口为 127.0.0.1:3333。目标列表代表配置入口，不能替代芯片兼容验证。';break;
case 'flash':b=`<div class="form-grid">${field('Flash 精确型号','chip',p.chip,{full:true,placeholder:'先识别，再粘贴 flashrom 返回的型号',help:'写入与擦除前必须指定型号，防止模糊匹配。'})}<div class="field full"><label>Flash 镜像（写入 / 校验需要）</label>${upload('.bin')}</div></div><div class="buttons">${button('flash.detect')}${button('flash.read',true)}${button('flash.verify')}${button('flash.write')}${button('flash.erase')}</div>`;help='需要模式 1 与编译了 ch347_spi 的 flashrom。建议先备份再写入；写入保留 flashrom 默认校验。此路径用于直接连接 SPI Flash，FPGA JTAG 间接烧录请使用 FPGA 下载页。';break;
case 'uart':{let ports=state.status?.ports?.filter(x=>state.device?.family==='rp2040'?x.path===state.device.port:x.vid===0x1a86)||[];b=`<div class="form-grid">${field('串口端口','port',p.port,{choices:state.mode===2?[['','HID UART1 · interface 0']]:[['','请选择设备端口'],...ports.map(x=>[x.path,x.path+' · '+x.description])]})}${field('波特率 · 8N1','baud',p.baud,{choices:[9600,19200,38400,57600,115200,230400,460800,921600,1000000,2000000,3000000].map(x=>[x,x.toLocaleString()])})}${field('UART 通道标记','channel',p.channel,{choices:state.mode===0?[[1,'UART1'],[0,'UART0']]:[[1,'UART1']],full:true,help:'通道标记不会切换物理端口；模式 0 的两个通道需选择各自对应的系统串口。'})}</div><div class="buttons">${button('uart.open',true)}${button('uart.close')}</div><div style="margin-top:23px">${field('发送文本 · 按原样发送','text',p.text,{area:true,full:true})}<div class="buttons">${button('uart.send')}<button data-clear-uart>清空显示</button></div></div><div class="section-title"><h2>串口接收</h2><span>UTF-8 · RX / TX</span></div><div class="terminal" id="uart-output" style="min-height:180px;max-height:280px">${esc(state.uart.map(x=>`[${new Date(x.time*1000).toLocaleTimeString()}] ${x.direction.toUpperCase()} ${x.text}`).join('\n')||'等待串口数据…')}</div>`;help='普通模式通过系统串口连接；模式 2 使用 HID UART。串口接口为 TTL 电平。模式 0 的 UART0 引脚复用请以新版原理图核对；当前默认不驱动 RTS / DTR。';break}
case 'i2c':b=`<div class="form-grid">${field('7 bit 设备地址','address',p.address)}${field('寄存器地址','register',p.register)}${field('寄存器地址宽度','reg_width',p.reg_width,{choices:[[1,'1 byte'],[2,'2 bytes · big endian']]})}${field('读取字节数','length',p.length)}${field('I²C 写入数据 · HEX','data',p.data,{full:true})}</div><div class="buttons">${button('i2c.scan')}${button('i2c.read',true)}${button('i2c.write')}</div><div id="i2c-addresses">${addressGrid()}</div><div class="section-title"><h2>SPI 全双工</h2><span>SCS0 · MSB first</span></div><div class="form-grid">${field('SPI mode','spi_mode',p.spi_mode,{choices:[[0,'0 · CPOL 0 / CPHA 0'],[1,'1 · CPOL 0 / CPHA 1'],[2,'2 · CPOL 1 / CPHA 0'],[3,'3 · CPOL 1 / CPHA 1']]})}${freq(p.freq)}${field('发送数据 · HEX','spi_data',p.spi_data,{area:true,full:true})}</div><div class="buttons">${button('spi.transfer',true)}</div>`;help='模式 1 使用 WCH SDK，模式 2 使用 HID。I²C 固定 100 kHz；HID 单事务读 ≤63 字节，写数据加寄存器地址 ≤62 字节。SPI 选择不高于请求值的硬件分频，最低 468.75 kHz。ACK 扫描也可能影响某些器件。';break;
case 'gpio':b=`<div class="form-grid">${field('GPIO 引脚','pin',p.pin,{choices:[[3,'GPIO3 · SCL'],[5,'GPIO5 · TRST / CS1'],[6,'GPIO6 · CTS1']],full:true})}${field('输出电平','value',p.value,{choices:[[0,'LOW · 0'],[1,'HIGH · 1']],full:true})}</div><div class="buttons">${button('gpio.read')}${button('gpio.write',true)}</div>`;help='此版本仅在模式 3 开放 GPIO3 / GPIO5 / GPIO6，通过官方 WCH SDK 读写。启动 OpenOCD 或 XVC 后会阻止 GPIO 操作。写入会把所选引脚配置为输出，需确认没有和目标输出或复位线冲突。HID GPIO 后端尚未开放。';break;
case 'jtag':b=`<div class="form-grid">${freq(p.freq)}${field('JTAG IR 长度','irlen',p.irlen)}${field('预期目标 IDCODE','idcode',p.idcode,{full:true})}<div class="field full"><label>单 TAP SVF 测试向量</label>${upload('.svf')}</div></div><div class="buttons">${button('jtag.svf',true)}</div><div class="section-title"><h2>Xilinx Virtual Cable</h2><span>实验功能 · 本机访问</span></div><div class="command">127.0.0.1:2542</div><div class="buttons">${button('xvc.start')}${button('xvc.stop')}</div>`;help='SVF 通过 OpenOCD 执行，当前配置适用于单 TAP 链；输入值必须与目标匹配。XVC 使用独立的实验性 CH347 USB 桥接，只监听本机。它提供 JTAG 桥接；Vivado / ILA 可用性仍需按器件和设计验证。';break;
}return workspace(b,title,help)}
function addressGrid(){let a=state.activeJob?.result?.addresses;if(!a)return '';return `<div class="section-title"><h2>应答地址</h2><span>${a.length} 个</span></div><div class="address-grid">${Array.from({length:112},(_,i)=>'0x'+(i+8).toString(16).padStart(2,'0').toUpperCase()).map(x=>`<span class="${a.includes(x)?'found':''}">${x}</span>`).join('')}</div>`}
function statusText(s){return ({succeeded:'已完成',failed:'失败',cancelled:'已取消',interrupted:'执行中断',running:'正在执行',queued:'等待执行'})[s]||s}
function history(){let jobs=currentJobs();return `<section class="panel"><div class="panel-header"><h2>${icon('history')}${state.demo?'演示任务记录':'本地任务记录'}</h2><button class="small" data-export-all>${icon('download')}导出记录</button></div>${jobs.length?`<div class="table-wrap"><table><thead><tr><th>操作 / 时间</th><th>模式</th><th>文件</th><th>状态</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${esc(j.title)}<small>${new Date(j.created*1000).toLocaleString()}</small></td><td class="mono">${modeName(j.mode)}</td><td>${esc(j.file?.name||'—')}<small>${j.file?.sha256?esc(j.file.sha256.slice(0,16))+'…':''}</small></td><td><span class="badge ${j.status}">${statusText(j.status)}</span></td><td><button class="small ghost" data-job="${j.id}">查看日志 ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">'+icon('history')+'<br>还没有任务记录。<br>运行一次扫描，即可查看完整的执行记录。</div>'}</section>${state.activeJob?`<div style="margin-top:20px">${output()}</div>`:''}`}
function wiring(){if(state.mode>=4)return rpWiring();const pins=[['1','TDO / MISO','目标输出 → 调试器'],['2','+3V3','电源输出；不是 VTref'],['3','TDI / MOSI','调试器输出 → 目标'],['4','CTS1 / GPIO6','流控或数字 I/O'],['5','TCK / SCK','时钟输出'],['6','RXD1','连接目标 TX'],['7','TMS / CS0','JTAG 控制 / 第一片选'],['8','TXD1','连接目标 RX'],['9','TRST / CS1 / GPIO5','复位 / 第二片选'],['10','SCL / GPIO3','I²C 时钟 / 数字 I/O'],['11','GND','与目标共地'],['12','SDA','I²C 数据']];return `${state.mode<=3?modeCards():`<div class="notice">${modeName(state.mode)} · 功能由板上固件决定；切换配置需要重新刷写 UF2。</div>`}<div class="guide-grid" style="margin-top:24px"><section class="panel"><div class="panel-header"><h2>${icon('nodes')}J2 接口参考</h2><span class="subtle">基于现有版</span></div><div class="table-wrap"><table><thead><tr><th>PIN</th><th>信号</th><th>说明</th></tr></thead><tbody>${pins.map(x=>'<tr>'+x.map(y=>`<td>${y}</td>`).join('')+'</tr>').join('')}</tbody></table></div></section><div><section class="panel"><div class="panel-header"><h2>${icon('book')}开始前检查</h2></div><div class="panel-body"><div class="guide-step"><span class="number">1</span><div><b>配置稳定的模式选择电平</b><p>DTR1 / RTS1 在上电时采样。使用明确的上拉、下拉或开关配置；避免同一路同时装入等值上下拉。</p></div></div><div class="guide-step"><span class="number">2</span><div><b>确认电压与引脚复用</b><p>现有板 +3V3 为供电输出，没有 VTref 自适应电平转换。连接前核实目标电压与新版引脚定义。</p></div></div><div class="guide-step"><span class="number">3</span><div><b>从低频扫描开始</b><p>JTAG 建议先用 1 MHz 扫描 IDCODE；SPI Flash 先识别并备份，再执行写入或擦除。</p></div></div><div class="guide-step"><span class="number">4</span><div><b>一次只让一个工具占用总线</b><p>Agent 串行执行硬件任务。使用 MCU 或 XVC 会话后，先停止会话再切换到其他总线工具。</p></div></div></div></section><div class="warning" style="margin-top:18px">SWD 需要相应芯片版本、适配接线及新版 OpenOCD。不能仅因为有 JTAG 引脚，就认为所有版本都支持 SWD。模式 0 的 UART0 需按 CH347T 引脚复用核对新版 PCB。</div></div></div>`}
function setup(){return `<div class="guide-grid"><section class="panel"><div class="panel-header"><h2>${icon('plug')}本地 Agent</h2><span class="badge">Python 3.10+</span></div><div class="panel-body"><div class="guide-step"><span class="number">1</span><div><b>下载并解压启动包</b><p>包含网页、本地桥接服务、测试、部署说明和可选 AI Agent。</p>${["127.0.0.1","localhost"].includes(location.hostname)?'<span class="subtle">当前已运行本地启动包，源码位于解压目录。</span>':'<a href="CH347_Debug_Studio.zip" download class="download-link">下载完整源码与启动包 ↗</a>'}</div></div><div class="guide-step"><span class="number">2</span><div><b>安装依赖并启动</b><p>Windows 双击 <code>start-windows.bat</code>；macOS / Linux 执行 <code>bash start.sh</code>。首次启动会创建虚拟环境并安装 Python 依赖。</p></div></div><div class="guide-step"><span class="number">3</span><div><b>配对本次连接</b><p>本地网页自动配对。在线网页点击连接，填入本次启动打印的配对码；浏览器询问本地网络权限时允许访问。</p><button class="primary" data-connect>${icon('plug')}连接本地 Agent</button></div></div><div class="help-box">若浏览器阻止在线页面访问 loopback，请使用启动后打开的 <b>http://127.0.0.1:8765</b>，全部功能相同。配对码只保存在当前页面内存中。</div></div></section><div>${dependency()}<section class="panel" style="margin-top:18px"><div class="panel-header"><h2>${icon('settings')}当前状态</h2><button class="small ghost" data-refresh>${icon('refresh')}刷新</button></div><div class="panel-body"><div class="summary-line"><span>服务地址</span><b class="mono">${esc(state.base)}</b></div><div class="summary-line"><span>操作系统</span><b>${esc(state.status?.platform||'—')}</b></div><div class="summary-line"><span>检测到的设备</span><b>${state.status?.devices?.length??'—'}</b></div><div class="summary-line"><span>AI 模型</span><b>${state.status?.ai?'eve 已配置':'未启用 · 规则助手可用'}</b></div>${(state.status?.warnings||[]).map(x=>`<div class="notice">${esc(x)}</div>`).join('')}<div class="buttons"><button data-demo>进入演示模式</button>${state.connected?'<button class="danger" data-disconnect>断开并停止会话</button>':''}</div></div></section></div></div><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>${icon('info')}功能与后端</h2><span class="subtle">已实现接口 · 待真机验收</span></div><div class="table-wrap"><table><thead><tr><th>用途</th><th>后端</th><th>要求</th></tr></thead><tbody><tr><td>FPGA</td><td>openFPGALoader</td><td>ch347_jtag 下载线</td></tr><tr><td>XVC · 实验功能</td><td>内置 CH347 USB 桥接</td><td>pyusb / libusb，模式 3；待真机验证</td></tr><tr><td>RP2040 SWD / UART</td><td>OpenOCD CMSIS-DAP / pyserial</td><td>本板 DAP 专用固件，3.3 V 接口</td></tr><tr><td>逻辑分析仪</td><td>PIO / DMA · SUMP8</td><td>本板 SUMP8 固件，8 通道，最多 100000 点</td></tr><tr><td>数字示波器</td><td>ADC / DMA · ADC12</td><td>本板 ADC12 固件，单路 0–3.3 V，最多 32768 点</td></tr><tr><td>MCU / SVF</td><td>OpenOCD</td><td>ch347 驱动与对应 target 配置</td></tr><tr><td>SPI Flash</td><td>flashrom</td><td>ch347_spi programmer，模式 1</td></tr><tr><td>I²C / SPI</td><td>WCH SDK / ch347api HID</td><td>模式 1：Windows / Linux SDK；模式 2：HID</td></tr><tr><td>GPIO</td><td>WCH SDK</td><td>模式 3；GPIO3 / 5 / 6</td></tr><tr><td>UART</td><td>pyserial / HID UART</td><td>系统串口驱动 / HID 权限</td></tr></tbody></table></div></section>`}
function render(){const meta=META[state.page];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('chip')}</span><div><div class="brandname">DEBUG</div><div class="brandsub">CH347 + RP2040</div></div></div><div class="nav">${navButton(NAV[0])}</div><div class="navgroup">DEVELOPMENT</div><nav class="nav">${NAV.slice(1,8).map(navButton).join('')}</nav><div class="navgroup">WORKSPACE</div><nav class="nav">${NAV.slice(8).map(navButton).join('')}</nav><div class="sidebar-bottom"><div class="version"><span><span class="dot"></span>LOCAL FIRST</span><span>v0.2</span></div><p>固件与设备访问留在本机。<br>每一步操作，都有迹可循。</p></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><span>Debug Studio</span><span>/</span><b>${NAV.find(x=>x[0]===state.page)[1]}</b></div><div class="top-actions">${badge()}<button class="primary" data-connect>${icon('plug')}${state.connected?'连接管理':'连接调试器'}</button></div></header><main class="main"><div class="heading"><div><div class="eyebrow">${meta[0]}</div><h1>${meta[1]}</h1><p>${meta[2]}</p></div><span class="pill">CH347 + RP2040</span></div>${profileSelector(state)}${state.page==='logic'||state.page==='scope'?instrumentPage({state,field,button,getform,output},state.page==='scope'):state.page==='firmwares'?firmwarePage():state.page==='home'?home():state.page==='history'?history():state.page==='wiring'?wiring():state.page==='setup'?setup():toolPage()}<footer class="footer"><span>DEBUG STUDIO / CH347 + RP2040</span><span>${state.demo?'DEMO ENVIRONMENT · NO USB ACCESS':'LOCAL EXECUTION · '+(state.connected?'CONNECTED':'DISCONNECTED')}</span></footer></main></div></div><nav class="mobile-nav">${NAV.map(x=>`<button data-nav="${x[0]}" class="${state.page===x[0]?'active':''}">${icon(x[2])}${x[1]}</button>`).join('')}</nav>`;bind()}
function navButton(n){return `<button data-nav="${n[0]}" class="${state.page===n[0]?'active':''}">${icon(n[2])}<span>${n[1]}</span>${n[0]==='home'?'<span class="navhint">⌘ 1</span>':''}</button>`}
function bind(){
 const deviceSelect=$('#device-select');if(deviceSelect)deviceSelect.onchange=()=>{if(state.busy){toast('请等待当前任务结束');render();return}if(state.demo){state.mode=+deviceSelect.value;state.device=null;}else{state.device=state.status.devices.find(d=>d.id===deviceSelect.value)||null;if(state.device)state.mode=state.device.mode;}state.activeJob=null;if([4,5,7].includes(state.mode)){state.page={4:'mcu',5:'logic',7:'scope'}[state.mode];if(state.mode===4){getform('mcu').transport='swd';getform('mcu').freq=1000000;}}render();};
 bindInstrument(state);
 document.querySelectorAll('[data-capture-file]').forEach(b=>b.onclick=async()=>{try{const f=state.activeJob.result.downloads.find(f=>f.id===b.dataset.captureFile);saveBlob(await api('download/'+f.id,null,true),f.name)}catch(e){toast(e.message)}});
document.querySelectorAll('[data-nav]').forEach(x=>x.onclick=()=>nav(x.dataset.nav));document.querySelectorAll('[data-mode]').forEach(x=>x.onclick=()=>{state.mode=+x.dataset.mode;render();if(!state.demo&&state.device?.mode!==state.mode)toast('已选择准备模式；请切换硬件并重新上电后再执行。')});document.querySelectorAll('[data-connect]').forEach(x=>x.onclick=connectModal);document.querySelectorAll('[data-op]').forEach(x=>x.onclick=()=>prepare(x.dataset.op));document.querySelectorAll('[data-field]').forEach(x=>x.oninput=()=>getform(state.page)[x.dataset.field]=x.value);document.querySelectorAll('[data-job]').forEach(x=>x.onclick=()=>{state.activeJob=currentJobs().find(j=>j.id===x.dataset.job);render()});document.querySelectorAll('[data-ask]').forEach(x=>x.onclick=()=>ask(x.dataset.ask));$('#ask-form')?.addEventListener('submit',e=>{e.preventDefault();ask($('#ask-input').value)});$('#firmware')?.addEventListener('change',e=>setfile(e.target.files[0]));const drop=$('#dropzone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.style.background='#eaf5ed'};drop.ondragleave=()=>drop.style.background='';drop.ondrop=e=>{e.preventDefault();setfile(e.dataTransfer.files[0])}}
 $('[data-export-job]')?.addEventListener('click',()=>exportJSON(state.activeJob,'ch347-task.json'));$('[data-export-all]')?.addEventListener('click',()=>exportJSON({source:state.demo?'demo':'hardware',tasks:currentJobs()},'ch347-history.json'));$('[data-cancel]')?.addEventListener('click',cancelJob);$('[data-download]')?.addEventListener('click',downloadBackup);$('[data-demo]')?.addEventListener('click',()=>{if(state.connected){toast('请先断开当前硬件会话，再进入演示模式。');return}state.demo=true;state.activeJob=null;state.uart=[];render()});$('[data-disconnect]')?.addEventListener('click',disconnect);$('[data-refresh]')?.addEventListener('click',async()=>{try{await refresh();render();toast('状态已刷新')}catch(e){toast(e.message)}});$('[data-clear-uart]')?.addEventListener('click',()=>{state.uart=[];state.uartSince=Date.now()/1000;render()})}
function modal(title,body,footer=''){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="${esc(title)}" class="modal"><div class="modal-head"><h2>${title}</h2><button class="ghost icon-button" id="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;$('#close-modal').onclick=closeModal;$('.modal-backdrop').onclick=e=>{if(e.target===$('.modal-backdrop'))closeModal()};setTimeout(()=>$('.modal input, .modal button')?.focus(),20)}
function closeModal(){$('#modal-root').innerHTML='';state.plan=null}
function connectModal(){modal('连接本地 Agent',`<p>先在连接调试器的电脑上启动本地 Agent，然后填写终端打印的本次配对码。</p><div class="field"><label for="agent-url">本地服务地址</label><input id="agent-url" value="${esc(state.base)}" spellcheck="false"></div><div class="field"><label for="agent-token">本次配对码</label><input id="agent-token" type="password" autocomplete="off" placeholder="粘贴 Agent 启动时打印的配对码" value="${esc(state.token)}"></div><div id="connect-error"></div><div class="help-box">默认地址为 http://127.0.0.1:8765。仅允许连接本机地址。<br>首次使用？在“连接设置”下载完整启动包。</div>`,`<button id="connect-guide">启动说明</button><button class="primary" id="do-connect">${icon('plug')}配对并检测设备</button>`);$('#connect-guide').onclick=()=>{closeModal();nav('setup')};$('#do-connect').onclick=async()=>{const b=$('#do-connect');b.disabled=true;b.textContent='正在连接…';try{let u=new URL($('#agent-url').value);if(!['127.0.0.1','localhost'].includes(u.hostname)||u.protocol!=='http:'||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('请输入 http://127.0.0.1:端口 或 http://localhost:端口');state.base=u.origin;state.token=$('#agent-token').value.trim();if(!state.token)throw Error('请填写配对码');await refresh();state.demo=false;state.activeJob=null;state.uart=[];closeModal();render();startPolling();toast(state.device?'已连接 '+modeName(state.device.mode):'Agent 已连接，请选择设备或刷新')}catch(e){state.connected=false;state.device=null;state.status=null;clearInterval(pollTimer);$('#connect-error').innerHTML=`<div class="error-box">${esc(e.message)}<br>如果浏览器限制本地网络，请使用 http://127.0.0.1:8765 打开的本地网页。</div>`;b.disabled=false;b.textContent='重新连接'}}}
async function api(path,data,raw=false){const r=await fetch(state.base+'/api/'+path,{method:data?'POST':'GET',headers:{'Authorization':'Bearer '+state.token,...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(path==='assistant'?95000:15000)});if(!r.ok){const e=await r.json().catch(()=>({error:'连接失败 HTTP '+r.status}));throw Error(e.error||'请求失败')}return raw?r.blob():r.json()}
async function refresh(){const s=await api('status');const old=state.device?.id;state.status=s;state.connected=true;state.device=s.devices.find(d=>d.id===old)||(s.devices.length===1?s.devices[0]:null);if(state.device)state.mode=state.device.mode;state.jobs=await api('jobs');if(s.devices.length>1&&!state.device)toast('检测到多个设备，请在设备列表选择本次操作的目标。')}

async function disconnect(){try{await api('disconnect',{});clearInterval(pollTimer);state.connected=false;state.status=null;state.device=null;state.token='';state.activeJob=null;state.uart=[];state.demo=false;render();toast('已停止调试与串口会话，断开配对')}catch(e){toast(e.message)}}
async function setfile(file){if(!file)return;if(!file.size||file.size>64*1024*1024){toast('请选择 1 字节至 64 MiB 的文件');return}try{let bytes=await file.arrayBuffer(),hash=await sha256(bytes);state.files[state.page]={name:file.name,size:file.size,sha256:hash,bytes};render()}catch(e){toast('文件读取失败：'+e.message)}}
async function prepare(op){if(state.busy)return;const p={...getform(state.page)};if(op==='spi.transfer')p.data=p.spi_data;const def=OP[op];if(!state.demo&&!state.connected){connectModal();return}if(!state.demo&&!state.device){toast('请在设备列表选择一个调试器，并刷新设备状态。');return}const mode=state.demo?state.mode:state.device.mode;if(!def[1].includes(mode)){toast(`此操作需要 ${def[1].map(modeName).join(' / ')}。当前是 ${modeName(mode)}；请切换对应设备或固件。`);return}let file=state.files[state.page];if(FILE_OPS.includes(op)&&!file){toast('请先选择固件或向量文件');return}state.busy=true;try{let plan;if(state.demo){plan={id:uuid(),op,title:def[0],write:def[2],device:{id:'DEMO',mode:mode,name:modeName(mode)+' 示例设备',version:'未检测'},params:p,file:file?{name:file.name,sha256:file.sha256,size:file.size}:null,confirmation:'DEMO',preview:demoCommand(op,p,file),warning:'这是演示计划。示例输出不代表真实器件状态。'}}else{if(FILE_OPS.includes(op)){let bytes=new Uint8Array(file.bytes),chunks=[];for(let i=0;i<bytes.length;i+=32768)chunks.push(String.fromCharCode(...bytes.subarray(i,i+32768)));const f=await api('upload',{name:file.name,data:btoa(chunks.join(''))});p.file_id=f.id}plan=await api('prepare',{op,device_id:state.device.id,params:p})}state.plan=plan;reviewPlan(plan)}catch(e){toast(e.message)}finally{state.busy=false}}
function demoCommand(op,p,f){if(op.startsWith('fpga.'))return ['openFPGALoader','-c','ch347_jtag','--freq',p.freq||'1000000',op==='fpga.detect'?'--detect':op==='fpga.sram'?'-m':'-f',f?.name||''].filter(Boolean);if(op.startsWith('flash.'))return ['flashrom','-p','ch347_spi',op==='flash.read'?'-r backup.bin':op==='flash.detect'?'':op==='flash.erase'?'-E':(op==='flash.verify'?'-v ':'-w ')+(f?.name||'')];return op+' '+JSON.stringify(p)}
function reviewPlan(plan){modal(state.demo?'预览演示任务':'确认执行计划',`<div class="summary-line"><span>操作</span><b>${esc(plan.title)}</b></div><div class="summary-line"><span>设备 / 模式</span><b>${esc(plan.device.name)}</b></div>${plan.file?`<div class="summary-line"><span>文件</span><b>${esc(plan.file.name)}</b></div><div class="file-hash" style="margin:12px 0 18px">SHA256 ${esc(plan.file.sha256)}</div>`:''}<p>${esc(plan.warning)}</p><div class="command">${esc(Array.isArray(plan.preview)?plan.preview.join(' '):plan.preview)}</div>${plan.write?'<label class="confirm-check"><input type="checkbox" id="confirm-write"><span>我已核对目标、接线与文件，确认执行此操作。<br>写入、擦除及调试控制可能改变目标状态。</span></label>':''}<div id="execute-error"></div>`,`<button id="cancel-plan">返回修改</button><button class="primary" id="execute-plan" ${plan.write?'disabled':''}>${icon('play')}${state.demo?'运行演示':plan.write?'确认并执行':'执行任务'}</button>`);$('#cancel-plan').onclick=closeModal;if(plan.write)$('#confirm-write').onchange=e=>$('#execute-plan').disabled=!e.target.checked;$('#execute-plan').onclick=()=>execute(plan)}
async function execute(plan){$('#execute-plan').disabled=true;try{if(state.demo){closeModal();let j={id:uuid(),title:plan.title,op:plan.op,mode:plan.device.mode,file:plan.file,created:Date.now()/1000,status:'running',logs:['[DEMO] 演示任务 · 未访问 USB','> '+(Array.isArray(plan.preview)?plan.preview.join(' '):plan.preview)],result:null};state.activeJob=j;state.demoJobs.unshift(j);state.busy=true;render();setTimeout(()=>{if(j.status!=='running')return;j.status='succeeded';j.logs.push('[DEMO] 示例事务完成。此结果仅用于界面预览。');j.result=demoResult(plan);if(plan.op==='uart.open')state.uart.push({time:Date.now()/1000,direction:'rx',text:'[DEMO] System ready. UART1 @ 115200 8N1\r\n'});if(plan.op==='uart.send')state.uart.push({time:Date.now()/1000,direction:'tx',text:plan.params.text});state.busy=false;render()},850)}else{let j=await api('execute',{plan_id:plan.id,confirmation:plan.write?plan.confirmation:''});closeModal();state.activeJob=j;state.busy=true;render();startPolling()}}catch(e){$('#execute-error').innerHTML=`<div class="error-box">${esc(e.message)}</div>`;$('#execute-plan').disabled=false}}
function demoResult(p){const op=p.op;if(op==='logic.capture'||op==='scope.capture')return demoCapture(op==='scope.capture',p.params);if(op==='fpga.detect')return {source:'DEMO',chain:[{idcode:'0x012BA043',manufacturer:'Lattice',part:'LCMXO2-1200HC',status:'示例 IDCODE'}]};if(op==='flash.detect')return {source:'DEMO',chip:'W25Q64.V',size:'8192 KiB'};if(op==='i2c.scan')return {source:'DEMO',addresses:['0x50','0x68']};if(op==='i2c.read')return {source:'DEMO',address:p.params.address,hex:'68 00 00 00 00 00 00 00'};if(op==='spi.transfer')return {source:'DEMO',rx:'00 EF 40 17'};if(op==='gpio.read')return {source:'DEMO',pins:[{pin:3,value:1},{pin:5,value:1},{pin:6,value:0}]};if(op==='mcu.registers')return {source:'DEMO',r0:'0x00000000',pc:'0x08000180',sp:'0x20002000'};return {source:'DEMO',note:'流程演示完成；未执行真实硬件操作。'}}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(!state.connected||state.demo)return;try{if(state.activeJob&&['running','queued'].includes(state.activeJob.status)){let j=await api('jobs/'+state.activeJob.id);if(j.id){state.activeJob=j;state.busy=['running','queued'].includes(j.status);updateOutput();if(!state.busy){state.jobs=await api('jobs');if(['history','logic','scope'].includes(state.page))render()}}}if(state.page==='uart'){state.uart=(await api('uart')).filter(x=>x.time>(state.uartSince||0));const el=$('#uart-output');if(el){el.textContent=state.uart.map(x=>`[${new Date(x.time*1000).toLocaleTimeString()}] ${x.direction.toUpperCase()} ${x.text}`).join('\n')||'等待串口数据…';el.scrollTop=el.scrollHeight}}}catch(e){toast('本地连接中断：'+e.message);clearInterval(pollTimer);state.connected=false;state.busy=false}},700)}
function updateOutput(){const el=$('#output-panel');if(el){el.outerHTML=output();$('[data-cancel]')?.addEventListener('click',cancelJob);$('[data-export-job]')?.addEventListener('click',()=>exportJSON(state.activeJob,'ch347-task.json'));$('[data-download]')?.addEventListener('click',downloadBackup);let t=$('#terminal-output');if(t)t.scrollTop=t.scrollHeight}document.querySelectorAll('[data-op]').forEach(b=>b.disabled=state.busy);if($('#i2c-addresses'))$('#i2c-addresses').innerHTML=addressGrid()}
async function cancelJob(){if(state.demo){state.activeJob.status='cancelled';state.activeJob.logs.push('[DEMO] 演示已取消');state.busy=false;render();return}try{await api('cancel',{job_id:state.activeJob.id});toast('已请求取消；正在等待执行进程退出。部分写入可能已发生。')}catch(e){toast(e.message)}}
function saveBlob(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportJSON(value,name){saveBlob(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),name)}
async function downloadBackup(){try{const f=state.activeJob.result.download;saveBlob(await api('download/'+f.id,null,true),f.name)}catch(e){toast(e.message)}}
async function ask(message){if(!message.trim())return;let p=null,answer='';if(state.status?.ai&&!state.demo){state.answer='正在分析任务…';render();try{let r=await api('assistant',{message});state.answer=r.text||'模型未返回回答。'}catch(e){state.answer='AI 调用失败：'+e.message}render();return}
 if(/示波|adc|模拟|电压波形/i.test(message)){p='scope';answer='RP2040 示波器需要 ADC12 专用固件。\n从 GP26、GP27、GP28 中选择一路，输入 0–3.3 V、与目标共地。选择采样率与深度后单次采集，支持游标、Vpp / RMS 与 CSV 导出。500 kSa/s 是采样率，不是模拟带宽。'}else if(/逻辑|时序|采集|波形/i.test(message)){p='logic';answer='RP2040 逻辑分析仪需要 SUMP8 专用固件。\nD0–D7 对应 GP20–GP27，可立即采集或按单通道边沿/电平触发。采集后可缩放、移动、设置游标，导出 CSV / VCD / PulseView .sr。切换固件方法见 RP2040 固件页。'}else if(/rp2040|pico|uf2/i.test(message)){p='firmwares';answer='本板接出 GP20–GP28，需要专用引脚配置。\n提供 SWD + UART、逻辑分析、ADC 示波器三种 UF2，按 BOOT 再插 USB，复制到 RPI-RP2 磁盘即可切换。三个配置不同时运行。'}else if(/fpga|bit|jed|下载/i.test(message)){p='fpga';answer='FPGA 下载使用模式 3。\n1. 连接 TCK、TMS、TDI、TDO 和 GND。\n2. 在 FPGA 下载页先扫描 JTAG 链，核对器件 ID。\n3. 选择配置文件；临时验证用 SRAM，持久配置用 Flash。\n4. 查看计划中的目标与 SHA-256，再确认执行。'}else if(/flash|备份|擦除/i.test(message)){p='flash';answer='SPI Flash 使用模式 1 和 flashrom ch347_spi。\n先识别 Flash，核实精确型号，再备份。备份完成后可以从输出区下载 .bin 文件。\n写入或擦除前需填写型号；写入完成由 flashrom 默认执行校验。'}else if(/stm32|mcu|单步|swd/i.test(message)){p='mcu';answer=state.mode===4?'RP2040 调试固件使用 OpenOCD CMSIS-DAP v2，支持 SWD + CDC UART。\n连接 SWCLK GP20、SWDIO GP21、GND；选择目标后启动调试。可暂停、单步、读取寄存器或烧录 ELF / HEX。不支持 JTAG / SWO。':'MCU 调试使用模式 3 和支持 ch347 的 OpenOCD。\n选择目标系列与接口，然后启动调试。CH347T 2.41 无原生 SWD，较新版本仍需验证。\n连接成功后可暂停、单步、读取寄存器和内存；外部 GDB 连接 127.0.0.1:3333。'}else if(/i.?c|寄存器|spi|总线/i.test(message)){p='i2c';answer='I²C / SPI 支持模式 1 的 WCH SDK 和模式 2 的 HID 后端。\nI²C 使用 7 bit 地址，先扫描或读取器件标识寄存器。注意读寄存器也可能清除状态。\nHID 单次读 ≤63 字节；写数据加寄存器地址 ≤62 字节。'}else if(/串口|uart|日志/i.test(message)){p='uart';answer='在串口终端选择系统端口和波特率，打开串口后会持续接收日志。\n模式 0 提供两个 UART；模式 2 使用 HID UART1。发送文本会按原样发送，包含你输入的换行。'}else if(/gpio|电平/i.test(message)){p='gpio';answer='GPIO 当前通过 WCH SDK 在模式 3 访问 GPIO3 / 5 / 6。\n请先停止 MCU 或 XVC 会话，再确认引脚没有与目标输出冲突。设置输出会改变该引脚方向。'}else if(/xvc|svf|jtag/i.test(message)){p='jtag';answer='JTAG / XVC 使用模式 3。\nSVF 需填写单 TAP 链的 IR 长度和 IDCODE。XVC 监听 127.0.0.1:2542。\n是否能使用 Vivado / ILA 取决于 FPGA 器件、设计和工具版本，需进一步真机确认。'}else{answer='我可以帮你定位 FPGA 下载、MCU 调试、串口、SPI Flash、I²C / SPI、GPIO 和 JTAG / XVC 的操作入口。\n请描述目标与任务，例如“备份 SPI Flash”。当前是规则助手，不会自动执行硬件操作。'}
 state.answer=(state.demo?'当前为演示模式，以下是操作建议。\n\n':'')+answer;if(p)state.answer+='\n\n→ 左侧选择「'+NAV.find(x=>x[0]===p)[1]+'」开始准备任务。';render()}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});render();
if(location.hash.startsWith('#pair=')){state.token=decodeURIComponent(location.hash.slice(6));state.base=location.origin;window.history.replaceState(null,'',location.pathname);refresh().then(()=>{state.demo=false;render();startPolling()}).catch(e=>toast('自动配对失败：'+e.message))}
